"use strict";
const DATA=JSON.parse(document.getElementById('atlas-data').textContent);
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=3)=>Number(n).toFixed(d);
const SOURCES=Object.fromEntries(DATA.sources.map(s=>[s.id,s]));
const CATS=Object.fromEntries(DATA.categories.map(c=>[c.id,c]));
const DOCS=DATA.corpus;
const tokenize=s=>(String(s).toLowerCase().match(/[a-z0-9]+/g)||[]);
DOCS.forEach(d=>{d.tokens=tokenize(d.text);d.tf={};d.tokens.forEach(t=>d.tf[t]=(d.tf[t]||0)+1);});
const vocab=[...new Set(DOCS.flatMap(d=>d.tokens))];
const df=t=>DOCS.filter(d=>d.tf[t]).length;
const idf=t=>Math.log((DOCS.length+1)/(df(t)+1))+1;
const avgdl=DOCS.reduce((a,d)=>a+d.tokens.length,0)/DOCS.length;
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*(b[i]||0),0);
const norm=a=>Math.sqrt(dot(a,a));
const cosine=(a,b)=>norm(a)&&norm(b)?dot(a,b)/(norm(a)*norm(b)):0;
const val=id=>$('#'+id).value, number=id=>Number(val(id)), checked=id=>$('#'+id).checked;
function sourceLine(ids){return `<div class="source-line"><span>READ THE SOURCE</span>${ids.map(id=>{let s=SOURCES[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.title)}">${esc(s.author.split(' · ')[0])} · ${s.year} ↗</a>`;}).join('')}</div>`;}
function range(id,label,min,max,step,value,help=''){return `<label class="control" for="${id}"><span>${label}<output id="${id}-value" for="${id}">${value}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}">${help?`<div class="control-help">${help}</div>`:''}</label>`;}
function select(id,label,options,value){return `<label class="control" for="${id}"><span>${label}</span><select id="${id}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function textInput(id,label,value,help=''){return `<label class="control" for="${id}"><span>${label}</span><input type="text" id="${id}" value="${esc(value)}" spellcheck="false">${help?`<div class="control-help">${help}</div>`:''}</label>`;}
function check(id,label,on=false){return `<label class="control check" for="${id}"><input type="checkbox" id="${id}" ${on?'checked':''}><span>${label}</span></label>`;}
function lab(id,title,tag,controls,wide=false){return `<section class="lab ${wide?'wide-lab':''}" aria-labelledby="${id}-title"><header class="lab-header"><div><span class="eyebrow">THE INTERACTIVE LAB</span><h2 id="${id}-title">${title}</h2></div><span class="lab-tag">${tag}</span></header><div class="lab-body"><div class="controls">${controls}</div><div class="result" id="${id}-result" aria-live="polite" aria-atomic="true"></div></div></section>`;}
function metrics(items){return `<div class="metric-grid">${items.map(([v,t])=>`<div class="metric"><strong>${v}</strong><small>${t}</small></div>`).join('')}</div>`;}
function rows(items,places=3){if(!items.length)return '<div class="empty">No matches. Try a broader query.</div>';const max=Math.max(...items.map(x=>x.score),.001);return items.map((x,i)=>`<div class="rank-row"><span class="rank-pos">${i+1}</span><div class="rank-label">${esc(x.label||`${x.d.id} · ${x.d.title}`)}${x.sub?`<small>${esc(x.sub)}</small>`:''}<div class="track"><b style="width:${Math.max(0,x.score/max*100)}%"></b></div></div><span class="rank-value">${num(x.score,places)}</span></div>`).join('');}
function corpus(){return `<details class="corpus-toggle"><summary>Inspect the shared teaching collection · 8 documents</summary><p class="control-help">Synthetic documents, not factual claims about products. Text labs index only the body shown below: lowercase alphanumeric tokens, no stemming, no stopword removal. Titles are display labels. Relevance grades are a teaching judgment for “solar battery storage”, not universal labels.</p><div class="corpus-list">${DOCS.map(d=>`<article class="corpus-doc"><h3><code>${d.id}</code>${esc(d.title)}</h3><p>${esc(d.text)}</p><span class="pill">${d.type} · ${d.year}</span><span class="pill warm">${d.tokens.length} tokens · relevance ${d.rel}/3</span></article>`).join('')}</div></details>`;}
const navGroups=[['START EXPLORING',[['overview','A map of retrieval'],['timeline','The timeline']]],['MATCH & REPRESENT',DATA.categories.slice(0,7).map(c=>[c.id,c.name])],['COMPOSE & SERVE',DATA.categories.slice(7,12).map(c=>[c.id,c.name])],['THE NEXT CHAPTER',[['frontier','Generative & agentic'],['evaluation','Evaluation & tradeoffs'],['sources','Papers & further reading']]]];
const TABLIST=navGroups.flatMap(g=>g[1]);
$('#tabs').innerHTML=navGroups.map(([name,items])=>`<div class="nav-group" role="presentation">${name}</div>${items.map(([id,title])=>`<button type="button" class="nav-tab" role="tab" id="tab-${id}" aria-controls="panel-${id}" aria-selected="false" tabindex="-1" data-tab="${id}"><span class="nav-no">${String(TABLIST.findIndex(x=>x[0]===id)+1).padStart(2,'0')}</span><span>${title}</span></button>`).join('')}`).join('');
function panel(id,body){return `<section id="panel-${id}" class="panel" role="tabpanel" tabindex="0" aria-labelledby="tab-${id}" hidden>${body}</section>`;}
function heading(kicker,title,question,intro,era=''){return `<div class="page-top"><span class="chapter-no">${kicker}</span><span class="era">${era}</span></div><h1 class="page-title">${title}</h1><div class="page-question">${question}</div><p class="intro">${intro}</p>`;}
const heroSVG=`<svg viewBox="0 0 460 392" role="img" aria-label="Diagram: exact word matches and semantic neighbors feed a combined ranked result list"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#bdc9bb"/></pattern><marker id="arrowhead" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="none" stroke="#90a69b" stroke-width="1.5"/></marker></defs><rect x="5" y="12" width="445" height="340" fill="url(#dots)" opacity=".5"/><circle cx="226" cy="180" r="127" fill="none" stroke="#d8e1d5"/><circle cx="226" cy="180" r="87" fill="none" stroke="#d8e1d5" stroke-dasharray="3 7"/><path d="M226 78L115 137 M226 78L339 137 M115 214L193 282 M339 214L260 282" stroke="#90a69b" stroke-width="1.4" fill="none" marker-end="url(#arrowhead)"/><rect x="117" y="32" width="218" height="49" rx="8" fill="#fffefa" stroke="#bacdbd"/><text x="135" y="53" font-family="monospace" font-size="8" fill="#7d8e81">THE INFORMATION NEED</text><text x="135" y="69" font-family="Georgia" font-size="14" fill="#203439">“power after sunset”</text><rect x="20" y="136" width="180" height="84" rx="8" fill="#fffefa" stroke="#c1d1c0"/><text x="37" y="158" font-family="monospace" font-size="8" fill="#087a72">01 / MATCH WORDS</text><rect x="36" y="172" width="63" height="25" rx="4" fill="#e5eee9"/><text x="44" y="188" font-family="monospace" font-size="10" fill="#087a72">battery</text><rect x="105" y="172" width="77" height="25" rx="4" fill="#f5e8dd"/><text x="112" y="188" font-family="monospace" font-size="10" fill="#ba583c">storage</text><rect x="250" y="136" width="188" height="84" rx="8" fill="#fffefa" stroke="#c1d1c0"/><text x="266" y="158" font-family="monospace" font-size="8" fill="#087a72">02 / MATCH MEANING</text><path d="M273 201L300 179L321 194L347 172L375 195L415 178" stroke="#c4d4bf" stroke-width="1" fill="none"/><circle cx="300" cy="179" r="4" fill="#087a72"/><circle cx="321" cy="194" r="3" fill="#9dbda4"/><circle cx="347" cy="172" r="5" fill="#ba583c"/><circle cx="375" cy="195" r="3" fill="#9dbda4"/><circle cx="415" cy="178" r="3" fill="#9dbda4"/><rect x="124" y="276" width="220" height="84" rx="8" fill="#203c3d"/><text x="141" y="298" font-family="monospace" font-size="8" fill="#b8d2bd">03 / FUSE &amp; RERANK</text><text x="141" y="321" font-family="monospace" font-size="9" fill="#82af9e">01</text><text x="165" y="321" font-family="Georgia" font-size="13" fill="#fffefa">Batteries balance the grid</text><text x="141" y="344" font-family="monospace" font-size="9" fill="#82af9e">02</text><text x="165" y="344" font-family="Georgia" font-size="13" fill="#fffefa">Power after sunset</text></svg>`;
function overview(){return `<div class="hero"><div><div class="eyebrow">UNIT 01 · INFORMATION RETRIEVAL</div><h1>From matching words<br>to finding <em>meaning.</em></h1><p class="hero-copy">A guided journey through the ideas behind search. Start with Boolean logic. Explore embeddings, ranking and fusion. Then see how modern systems search for evidence, step by step.</p><div class="hero-actions"><a class="primary" href="#timeline">Explore the timeline <span>↗</span></a><a class="text-link" href="#boolean">Start with Boolean search →</a></div></div><div class="hero-visual">${heroSVG}<p class="hero-caption">DIFFERENT SIGNALS. ONE INFORMATION NEED.</p></div></div><div class="stats"><div class="stat"><b>${DATA.categories.length+1}</b><span>method & evaluation families</span></div><div class="stat"><b>${DATA.categories.reduce((n,c)=>n+c.methods.length,0)}</b><span>methods & related concepts</span></div><div class="stat"><b>14</b><span>interactive learning labs</span></div><div class="stat"><b>${DATA.sources.length}</b><span>papers, chapters & guides</span></div></div><div class="section-head"><h2>First, separate the moving parts.</h2><span class="eyebrow">A USEFUL MENTAL MODEL</span></div><p class="lead">Search is a pipeline of choices. The representation, lookup algorithm and relevance model are related, but each answers a different question.</p><div class="concept-grid"><div class="concept"><span class="concept-no">01 / REPRESENT</span><h3>What do we compare?</h3><p>Terms, sparse weights, dense vectors, token vectors, entities or page patches.</p><span class="pill">BM25 · DPR · SPLADE</span></div><div class="concept"><span class="concept-no">02 / RETRIEVE</span><h3>Where do we look?</h3><p>Find a broad candidate set using postings, exact scans, ANN or graph traversal.</p><span class="pill">Inverted index · HNSW</span></div><div class="concept"><span class="concept-no">03 / ORDER</span><h3>What belongs first?</h3><p>Combine result lists and spend extra computation on the most promising items.</p><span class="pill">RRF · Cross-encoder</span></div><div class="concept"><span class="concept-no">04 / VERIFY</span><h3>Did we find the evidence?</h3><p>Measure coverage, ranking, diversity, latency and downstream usefulness.</p><span class="pill">Recall · nDCG · Cost</span></div></div><div class="note"><strong>Old ideas remain active.</strong> Boolean filters, BM25 and learned models often coexist. This atlas covers the major families and their composition; no finite guide can enumerate every model, index or specialized domain.</div><div class="section-head"><h2>Choose a way into the atlas.</h2><span class="eyebrow">ONE TAB PER FAMILY</span></div><div class="map-grid">${DATA.categories.map((c,i)=>`<a class="map-item" href="#${c.id}"><span class="map-number">${String(i+1).padStart(2,'0')}</span><div><h3>${c.name}</h3><p>${c.subtitle}</p></div><span class="arrow">↗</span></a>`).join('')}<a class="map-item" href="#evaluation"><span class="map-number">14</span><div><h3>Evaluation & tradeoffs</h3><p>Measure what the pipeline actually recovers.</p></div><span class="arrow">↗</span></a></div><div class="section-head"><h2>A suggested learning path.</h2><span class="eyebrow">BUILD YOUR INTUITION</span></div><div class="pathway"><a href="#boolean">Boolean</a><span>→</span><a href="#lexical">TF–IDF</a><span>→</span><a href="#probabilistic">BM25</a><span>→</span><a href="#dense">Dense</a><span>→</span><a href="#fusion">Fusion</a><span>→</span><a href="#ranking">Reranking</a><span>→</span><a href="#evaluation">Evaluate</a></div><p class="lead">Each family explains the intuition, a concrete calculation, when it helps and where it fails. Open the method notes for detail. Use the labs to test one assumption at a time.</p>${corpus()}<div class="note warm"><strong>How to read the demos.</strong> Boolean sets, TF–IDF, BM25, language-model likelihood, vector similarity, MaxSim, IVF-style probing, RRF, MMR and evaluation metrics are calculated in your browser. Neural vectors, term weights and reranker scores are hand-authored teaching inputs. No neural model or external API runs here.</div><div class="section-head"><h2>Read the ideas at their source.</h2><a class="text-link" href="#sources">Browse all ${DATA.sources.length} references ↗</a></div><div class="source-preview"><div><a href="${SOURCES.bm25.url}" target="_blank" rel="noopener">BM25 and Beyond · Robertson & Zaragoza ↗</a><p>A foundation for understanding lexical evidence.</p></div><div><a href="${SOURCES.brightpro.url}" target="_blank" rel="noopener">Agentic search and complementary evidence · 2026 ↗</a><p>A recent direction in how retrieval is evaluated.</p></div></div>`;}
function timeline(){return heading('A BRIEF HISTORY','Search did not evolve in a straight line.','New branches grew. Earlier ideas kept working.','Follow selected landmarks from statistical indexing and Boolean sets to modern evidence-seeking systems. Dates mark papers or development periods; first preprints and later publications are distinguished where useful.','1957 → 2026')+`<div class="timeline-tools" role="group" aria-label="Filter historical era">${[['all','All eras'],['early','Before 2000'],['middle','2000–2020'],['recent','2021–2026']].map(([v,t])=>`<button class="chip" type="button" data-era="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('')}</div><p class="timeline-legend">Select a milestone to see why it mattered, read the source and jump to its method family.</p><div class="timeline-layout"><div class="timeline-list" id="timeline-list"></div><div class="timeline-detail" id="timeline-detail" aria-live="polite"></div></div><div class="note">The underlying ideas predate many landmark papers. Boolean logic is older than computerized retrieval; the periods shown here describe information-retrieval practice. A timeline is a map of influential developments, not a claim of sole invention.</div>`;}
function methodCard(m,c,i){return `<details class="method" id="method-${c.id}-${i}" ${i===0?'open':''}><summary><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${m.tag}</span><h3>${esc(m.title)}</h3></div></summary><div class="method-content"><p>${esc(m.idea)}</p><div class="formula">${esc(m.formula)}</div><h4>A concrete example</h4><p class="example">${esc(m.example)}</p><h4>When it helps</h4><p>${esc(m.use)}</p><h4>Where it can fail</h4><p>${esc(m.limit)}</p>${sourceLine(m.refs)}</div></details>`;}
function categoryPanel(c,i){return heading(`METHOD FAMILY ${String(i+1).padStart(2,'0')}`,c.name,c.question,c.intro,c.era)+sourceLine(c.sources)+`<div class="note">${esc(c.insight)}</div>`+labMarkup(c.id)+`<div class="section-head"><h2>The methods, unpacked.</h2><button type="button" class="small-button" data-expand="${c.id}">Expand all notes</button></div><div class="method-grid">${c.methods.map((m,j)=>methodCard(m,c,j)).join('')}</div>`+(['boolean','lexical','probabilistic','expansion','ranking','fusion'].includes(c.id)?corpus():'')+`<div class="panel-bottom">${i?`<a href="#${DATA.categories[i-1].id}">← ${DATA.categories[i-1].name}</a>`:'<a href="#timeline">← The timeline</a>'}<a href="#${i<DATA.categories.length-1?DATA.categories[i+1].id:'evaluation'}">${i<DATA.categories.length-1?DATA.categories[i+1].name:'Evaluation & tradeoffs'} →</a></div>`;}
function labMarkup(id){
 switch(id){
 case 'boolean':return lab('boolean','Build a search rule.','EXACT SET CALCULATIONS',textInput('bool-query','Boolean expression','solar AND (battery OR storage)','Explicit AND / OR / NOT, parentheses and quoted phrases. NOT > AND > OR. No implicit operators.')+`<div class="tile-row"><button class="small-button" data-bool='"battery storage"'>Try a phrase</button><button class="small-button" data-bool='storage AND NOT battery'>Try exclusion</button></div>`+check('bool-filter','Only reports from 2020 onward')+'<div class="note">No relevance sorting: matches retain collection order. Body tokens only.</div>');
 case 'lexical':return lab('lexical','Watch rare words gain weight.','REAL TF–IDF & COSINE',textInput('lex-query','Query','solar battery storage')+select('lex-mode','Ranking rule',[['cosine','TF–IDF + cosine'],['dot','Unnormalized TF–IDF dot product']],'cosine')+'<div class="note">Raw TF; smoothed IDF = ln((N+1)/(df+1))+1. Query and documents share the same weighting. No stemming.</div>');
 case 'probabilistic':return lab('probabilistic','Tune the lexical evidence.','REAL BM25 & LIKELIHOOD',textInput('bm-query','Query','solar battery storage')+select('bm-mode','Scoring model',[['bm25','BM25 · positive log1p IDF'],['lm','Query likelihood · Dirichlet smoothing']],'bm25')+range('bm-k1','k₁ · TF saturation',0,3,.1,1.2,'At 0, counts become binary; larger values reward repetition more.')+range('bm-b','b · length normalization',0,1,.05,.75,'0 ignores length. 1 applies the full length ratio.')+range('lm-mu','μ · collection smoothing',1,300,1,100,'Used only in language-model mode. Larger μ gives the background collection more influence.'));
 case 'expansion':return lab('expansion','One request. Several formulations.','REWRITE + REAL RETRIEVAL',select('exp-mode','Reformulation strategy',[['original','Original query'],['synonym','Controlled synonyms'],['pseudo','Pseudo-feedback · top document terms'],['hyde','Hypothetical answer-like rewrite']],'original')+range('exp-weight','Expansion weight',0,1,.1,.6,'Relative to original query term weights of 1. These explicit rewrites are teaching fixtures, not LLM output.')+`<p class="control-help">Original: “power after sunset”. Compare the candidate sets, then inspect why a new match appeared.</p>`);
 case 'dense':return lab('dense','Make semantic distance visible.','HAND-AUTHORED VECTORS',range('dense-angle','Query direction · degrees',0,90,1,30,'These two illustrative axes are energy storage and transport. Real neural dimensions are not usually interpretable.')+select('dense-metric','Similarity function',[['cosine','Cosine · normalized direction'],['dot','Dot product · magnitude matters']],'cosine')+check('dense-scale','Scale the car vector by 3')+`<div class="note">q=[cos θ, sin θ]. Document vectors are shown in full. This is exact geometry on invented inputs, not a benchmark of trained embeddings.</div>`);
 case 'sparse':return lab('sparse','Give a query new vocabulary.','FIXED WEIGHTS · REAL DOT PRODUCT',range('sparse-expansion','Learned expansion strength',0,1,.1,.8)+range('sparse-threshold','Prune weights below',0,1,.05,.2,'Pruning affects query weights. The document vectors are fixed.')+`<p class="control-help">Query: “renewable storage”. The synthetic model can activate battery, solar and grid. Move the threshold to see which bridges disappear.</p>`);
 case 'late':return lab('late','Inspect token-by-token matching.','FIXED MATRIX · REAL MAXSIM',select('late-doc','Document token matrix',[['balanced','A · solar + storage evidence'],['one','B · strong solar, weak storage'],['duplicate','C · the same evidence repeated']],'balanced')+check('late-storage','Include query token “storage”',true)+`<div class="note">Cells are illustrative token similarities. Highlighted values are row maxima. Adding duplicate document tokens cannot increase a row maximum.</div>`);
 case 'indexes':return lab('indexes','Probe fewer neighborhoods.','TOY IVF · EXACT DISTANCES',range('ivf-probe','nprobe · clusters visited',1,3,1,1,'Search the closest coarse centroids, then exactly score items inside those clusters.')+range('ivf-y','Query vertical position',.1,.9,.05,.5)+`<p class="control-help">Six 2D points, three fixed clusters, top-2 lookup. This demonstrates IVF-style partition misses, not HNSW or a full Faiss implementation.</p>`);
 case 'ranking':return lab('ranking','A better order needs a better shortlist.','FIXED RERANKER SCORES',range('rerank-depth','Candidate depth from BM25',1,8,1,3)+check('rerank-on','Apply the illustrative reranker',true)+`<div class="note">Query: “solar battery storage”. The candidate order is really computed with BM25. Reranker scores are fixed synthetic values, not neural inference.</div>`);
 case 'fusion':return lab('fusion','Combine the lists. Inspect every vote.','REAL FUSION & DIVERSITY',select('fusion-mode','Combination rule',[['rrf','Weighted reciprocal rank fusion'],['score','Min–max normalized score blend'],['mmr','MMR · relevance vs diversity']],'rrf')+range('fusion-depth','Candidate depth per list',1,8,1,4)+range('fusion-k','RRF smoothing constant k',0,100,1,60)+range('fusion-alpha','Lexical weight α / MMR relevance λ',0,1,.05,.5,'RRF: weights α and 1−α. Score blend: same weights. MMR: λ weights relevance after equal-weight RRF.')+check('fusion-duplicate','Add a duplicate lexical list','')+`<div class="note">Lexical scores are calculated BM25; semantic scores are illustrative. Equal-weight RRF here is half the unweighted sum, preserving the order.</div>`);
 case 'structured':return lab('structured','Follow a question across evidence.','DETERMINISTIC GRAPH WALK',select('graph-mode','Retrieval unit',[['one','One hop · products'],['two','Two hops · materials'],['summary','Community summary · broader context']],'one')+check('graph-edge','Include product → material evidence',true)+`<p class="control-help">Synthetic question: “Which material is used by the product Aurora makes?” This graph walk illustrates a join. The summary option is a fixed teaching summary, not GraphRAG inference.</p>`);
 case 'multimodal':return lab('multimodal','What survives the representation?','SCHEMATIC PAGE RETRIEVAL',select('visual-mode','Index representation',[['text','Flattened text only'],['layout','Text + table row structure'],['visual','Page image + visual regions']],'text')+select('visual-query','Information need',[['table','Which row has the longest cycle life?'],['chart','Which curve declines fastest?']],'table')+`<div class="note">This is a deterministic illustration of retained evidence, not CLIP or ColPali predictions. Neural retrieval still needs task-specific evaluation.</div>`);
 case 'frontier':return lab('frontier','Search for the missing evidence.','SCRIPTED AGENT TRACE',range('agent-budget','Search-call budget',1,3,1,1)+check('agent-diverse','Target an uncovered evidence aspect',true)+`<p class="control-help">Synthetic task: compare cost and durability of two storage options. Every step is a prewritten example with a real coverage calculation. No agent or LLM runs.</p>`);
 }
 return '';
}
function evaluation(){return heading('EVALUATION & TRADEOFFS','A better score for what, exactly?','Coverage, ordering and utility are different goals.','Use a fixed information need and a judged collection. Measure whether relevant documents enter the candidate set, how early they appear, and whether the selected evidence supports the task. Report quality alongside latency, index size and query cost.','Cranfield tradition → agentic evaluation')+sourceLine(['eval','beir','bright','brightpro'])+`<div class="note"><strong>Ground truth in this lab:</strong> eight synthetic documents, grades 0–3 for “solar battery storage”. Grades greater than zero count as relevant for precision, recall and reciprocal rank. nDCG uses gains 2<sup>grade</sup>−1. There are five relevant documents in the full collection.</div>`+lab('evaluation','Reorder the results. Measure the difference.','REAL RANKING METRICS',range('eval-k','Evaluate the top k',1,8,1,5)+select('eval-preset','Starting order',[['bm25','BM25 order'],['ideal','Ideal relevance order'],['reverse','Worst grade order'],['semantic','Illustrative semantic order']],'bm25')+`<div><span class="eyebrow">TRY THIS</span><p class="control-help">Move D2 above D6. Then move a zero-grade document to the top. Watch which metrics change and which do not.</p><button class="small-button" id="eval-reset" type="button">Reset order</button></div>`,true)+`<div class="section-head"><h2>Choose a metric to match the decision.</h2></div><div class="method-grid"><article class="method"><div class="method-content"><h3 style="margin-top:20px">Candidate coverage</h3><p>Recall@k = relevant items in the first k results / relevant items in the collection. Candidate recall sets a ceiling for downstream rerankers restricted to that set.</p><div class="formula">ANN Recall@k = |approximate top-k ∩ exact vector top-k| / k</div><p>ANN recall checks index approximation. It is a separate quantity from relevance recall.</p></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">Order and graded relevance</h3><p>RR@k credits only the first relevant result. MRR averages reciprocal rank across queries. AP credits precision at each relevant rank; MAP averages AP across queries.</p><div class="formula">nDCG@k = Σi≤k (2^gradeᵢ−1)/log₂(i+1) / ideal_DCG@k</div><p>A single-query reciprocal rank is RR, not MRR. The ideal DCG is computed over the full judged collection.</p></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">A reproducible experiment</h3><p>Hold the corpus, judgments, filters and candidate budget fixed. Tune on validation queries, report on held-out queries, and compare multiple domains and languages. Report uncertainty across queries.</p><p>Use exact scan to isolate ANN losses. Compare lexical, dense and hybrid baselines; change one component at a time and record index-build and refresh costs.</p></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">What common scores miss</h3><p>Incomplete judgments can mark useful new documents as irrelevant. Near-duplicate chunks can inflate apparent coverage. A topical hit can still lack the evidence needed for reasoning.</p><p>Measure aspect coverage, provenance and answer faithfulness when relevant. BEIR tests domain transfer; BRIGHT and BRIGHT-Pro ask harder questions about reasoning and complementary evidence.</p></div></article></div>${corpus()}<div class="quiz"><h3>Check your intuition.</h3><p>A relevant document is absent from the top-100 candidate set. Can a reranker restricted to those 100 documents move it to rank 1?</p><button type="button" class="small-button" data-quiz="wrong">Yes, with a stronger model</button><button type="button" class="small-button" data-quiz="right">No, change the candidate set</button><div class="quiz-answer" id="quiz-answer" aria-live="polite"></div></div>`;}
function library(){const kinds=[...new Set(DATA.sources.map(s=>s.kind))],cats=[...new Set(DATA.sources.map(s=>s.category))].sort();return heading('THE READING ROOM','Follow the trail back to the papers.','Foundations, landmarks and useful perspectives.','An annotated reading collection, researched for this guide. Follow the chapter citations for the specific method you are exploring, or filter the collection below. Notes explain why each source matters; publication and access dates are distinguished.','Checked '+DATA.checked)+`<div class="reading-path"><div><span class="eyebrow">01 / FOUNDATIONS</span><h3>Learn the vocabulary.</h3>${['boolean','vsm','bm25'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title} ↗</a>`).join('')}</div><div><span class="eyebrow">02 / MODERN RETRIEVAL</span><h3>Compare representations.</h3>${['dpr','splade','colbert'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title.split(':')[0]} ↗</a>`).join('')}</div><div><span class="eyebrow">03 / SYSTEMS & FRONTIERS</span><h3>Question the pipeline.</h3>${['rrf','bright','brightpro'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title.split(':')[0]} ↗</a>`).join('')}</div></div><div class="library-filters"><label for="paper-search">SEARCH TITLES, AUTHORS OR NOTES<input type="search" id="paper-search" placeholder="Try: fusion, reasoning, sparse…"></label><label for="paper-kind">SOURCE TYPE<select id="paper-kind"><option value="all">All source types</option>${kinds.map(k=>`<option>${k}</option>`).join('')}</select></label><label for="paper-category">SUBJECT<select id="paper-category"><option value="all">All subjects</option>${cats.map(k=>`<option>${k}</option>`).join('')}</select></label></div><p class="library-count" id="paper-count" aria-live="polite"></p><div id="paper-list"></div><div class="note warm">This is a curated research snapshot, not an exhaustive bibliography or live leaderboard. A historical claim of state-of-the-art performance applies to its paper’s task, date and evaluation protocol. No numbers in the teaching labs are measured model results.</div>`;}
$('#main').innerHTML=panel('overview',overview())+panel('timeline',timeline())+DATA.categories.map((c,i)=>panel(c.id,categoryPanel(c,i))).join('')+panel('evaluation',evaluation())+panel('sources',library());

let activeTab='overview';
function navigate(id,{focus=false,scroll=true}={}){if(!TABLIST.some(x=>x[0]===id))id='overview';activeTab=id;$$('[role=tab]').forEach(t=>{let on=t.dataset.tab===id;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;});$$('.panel').forEach(p=>p.hidden=p.id!=='panel-'+id);$('#menu-toggle').setAttribute('aria-expanded','false');$('.sidebar').classList.remove('menu-open');$('#menu-toggle').innerHTML=`${esc(TABLIST.find(x=>x[0]===id)[1])}<span aria-hidden="true">＋</span>`;if(focus)$('#tab-'+id).focus();if(scroll)window.scrollTo({top:0,behavior:'instant'});document.title=TABLIST.find(x=>x[0]===id)[1]+' — The Retrieval Atlas';}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){location.hash=b.dataset.tab;}});
$('#tabs').addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]'))return;let i=TABLIST.findIndex(x=>x[0]===activeTab);if(['ArrowDown','ArrowRight'].includes(e.key))i=(i+1)%TABLIST.length;else if(['ArrowUp','ArrowLeft'].includes(e.key))i=(i-1+TABLIST.length)%TABLIST.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=TABLIST.length-1;else return;e.preventDefault();history.replaceState(null,'','#'+TABLIST[i][0]);navigate(TABLIST[i][0],{focus:true});});
