document.addEventListener('click',e=>{let b=e.target.closest('[data-expand]');if(b){let notes=$$('.method', $('#panel-'+b.dataset.expand)),open=notes.some(n=>!n.open);notes.forEach(n=>n.open=open);b.textContent=open?'Collapse all notes':'Expand all notes';}let preset=e.target.closest('[data-bool]');if(preset){$('#bool-query').value=preset.dataset.bool;updateBoolean();}let q=e.target.closest('[data-quiz]');if(q){$('#quiz-answer').textContent=q.dataset.quiz==='right'?'Correct. Improve recall through retrieval, expansion, another source or a deeper candidate budget. Reranking only changes the supplied order.':'A stronger model can reorder only its supplied candidates. The missing document first needs to enter the candidate set.';}});
