window.addEventListener('beforeprint',()=>{if(printFilters)return;printState=$$('details').map(d=>[d,d.open]);printFilters={era:eraFilter,selection:timelineSelection,query:val('paper-search'),kind:val('paper-kind'),category:val('paper-category')};$$('details').forEach(d=>d.open=true);renderTimeline('all',0);$('#paper-search').value='';$('#paper-kind').value='all';$('#paper-category').value='all';renderPapers();});
