function bind(ids,fn){ids.forEach(id=>$('#'+id).addEventListener('input',()=>{let o=$('#'+id+'-value');if(o)o.textContent=val(id);fn();}));fn();}
function bm25(query,k1=1.2,b=.75){const terms=[...new Set(tokenize(query))];return DOCS.map(d=>({d,score:terms.reduce((s,t)=>{const tf=d.tf[t]||0;return s+(tf?Math.log(1+(DOCS.length-df(t)+.5)/(df(t)+.5))*tf*(k1+1)/(tf+k1*(1-b+b*d.tokens.length/avgdl)):0);},0)})).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));}
function lexical(query,mode='cosine'){const qt=typeof query==='string'?tokenize(query).reduce((a,t)=>(a[t]=(a[t]||0)+1,a),{}):query;const terms=[...new Set([...vocab,...Object.keys(qt)])];const q=terms.map(t=>(qt[t]||0)*idf(t));return DOCS.map(d=>{let v=terms.map(t=>(d.tf[t]||0)*idf(t));return {d,score:mode==='cosine'?cosine(q,v):dot(q,v)};}).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));}
function booleanAST(query){const re=/\s*("[^"]*"|\(|\)|[a-zA-Z0-9_-]+)/y;let pos=0,tokens=[],m;while(pos<query.length){if(!query.slice(pos).trim())break;re.lastIndex=pos;m=re.exec(query);if(!m)throw Error('Unsupported character or an unclosed quote near “'+query.slice(pos,pos+16)+'”.');tokens.push(m[1]);pos=re.lastIndex;}if(!tokens.length)throw Error('Enter a term or Boolean expression.');let i=0;function atom(){const t=tokens[i++];if(!t)throw Error('Expected a term.');if(t==='NOT')return {op:'NOT',a:atom()};if(t==='('){const x=or();if(tokens[i++]!==')')throw Error('Close the parenthesis.');return x;}if(['AND','OR',')'].includes(t))throw Error('Expected a term before '+t+'.');return {op:'TERM',term:t};}function and(){let a=atom();while(tokens[i]==='AND'){i++;a={op:'AND',a,b:atom()};}return a;}function or(){let a=and();while(tokens[i]==='OR'){i++;a={op:'OR',a,b:and()};}return a;}let ast=or();if(i!==tokens.length)throw Error('Use explicit AND or OR between terms. Operators must be uppercase.');return ast;}
function matchAST(ast,d){if(ast.op==='AND')return matchAST(ast.a,d)&&matchAST(ast.b,d);if(ast.op==='OR')return matchAST(ast.a,d)||matchAST(ast.b,d);if(ast.op==='NOT')return !matchAST(ast.a,d);if(ast.term.startsWith('"')){const ts=tokenize(ast.term);return ts.length>0&&d.tokens.some((_,i)=>ts.every((t,j)=>d.tokens[i+j]===t));}return !!d.tf[ast.term.toLowerCase()];}
function updateBoolean(){try{let ast=booleanAST(val('bool-query')),matches=DOCS.filter(d=>matchAST(ast,d)),filtered=matches.filter(d=>!checked('bool-filter')||(d.type==='report'&&d.year>=2020));$('#boolean-result').innerHTML=`<h3>${filtered.length} documents satisfy the rule.</h3><div class="formula">${esc(val('bool-query'))}${checked('bool-filter')?' AND [type=report, year≥2020]':''}</div><div class="table-wrap"><table class="mini-table"><thead><tr><th>Document</th><th>Rule</th><th>Eligible</th><th>Return</th></tr></thead><tbody>${DOCS.map(d=>{let hit=matches.includes(d),eligible=!checked('bool-filter')||(d.type==='report'&&d.year>=2020);return `<tr><td>${d.id} · ${esc(d.title)}</td><td class="${hit?'hit':'miss'}">${hit?'✓':'—'}</td><td>${eligible?'✓':'—'}</td><td>${hit&&eligible?'<span class="status">IN</span>':'—'}</td></tr>`;}).join('')}</tbody></table></div><p>Membership is calculated over all 8 body-token lists. Matching is case-insensitive for terms; operators use uppercase. “NOT battery” means the complement within this collection.</p>`;}catch(e){$('#boolean-result').innerHTML=`<h3>Check the expression.</h3><p>${esc(e.message)}</p>`;}}
function updateLexical(){const q=val('lex-query'),terms=[...new Set(tokenize(q))],res=lexical(q,val('lex-mode'));$('#lexical-result').innerHTML=`<h3>${val('lex-mode')==='cosine'?'Direction over raw size.':'Magnitude changes the order.'}</h3>${rows(res.filter(x=>x.score>0))}<div class="table-wrap"><table class="mini-table"><thead><tr><th>Query term</th><th>df / 8</th><th>Smoothed IDF</th></tr></thead><tbody>${terms.map(t=>`<tr><td>${esc(t)}</td><td>${df(t)} / 8</td><td>${num(idf(t))}</td></tr>`).join('')}</tbody></table></div><p>Scores use every vocabulary dimension in document normalization. Zero-overlap documents score zero. TF–IDF dot products have no fixed upper bound; cosine is bounded by 1 here because weights are nonnegative.</p>`;}
function updateBM(){let q=val('bm-query'),terms=tokenize(q),mode=val('bm-mode'),res;if(mode==='bm25')res=bm25(q,number('bm-k1'),number('bm-b'));else res=DOCS.map(d=>({d,score:terms.reduce((s,t)=>{let total=DOCS.reduce((s,x)=>s+(x.tf[t]||0),0),count=DOCS.reduce((s,x)=>s+x.tokens.length,0),p=((d.tf[t]||0)+number('lm-mu')*total/count)/(d.tokens.length+number('lm-mu'));return s+Math.log(p);},0)})).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));['bm-k1','bm-b'].forEach(id=>$('#'+id).disabled=mode!=='bm25');$('#lm-mu').disabled=mode!=='lm';if(!terms.length){$('#probabilistic-result').innerHTML='<h3>Enter a query.</h3>';return;}if(mode==='lm'&&terms.some(t=>!df(t))){$('#probabilistic-result').innerHTML='<h3>A query word is absent from the collection.</h3><p>Collection smoothing alone gives that token zero probability, so every document has log likelihood −∞. This lab does not invent an unknown-token probability. Try words present in the collection.</p>';return;}let list=mode==='bm25'?rows(res.filter(x=>x.score>0)):rows(res.map(x=>({...x,score:Math.exp(x.score/terms.length)})),4);$('#probabilistic-result').innerHTML=`<h3>${mode==='bm25'?'Diminishing returns. Length matters.':'How likely are these query tokens?'}</h3>${list}<div class="formula">N=8 · avgdl=${num(avgdl,2)} tokens<br>${mode==='bm25'?`k₁=${val('bm-k1')} · b=${val('bm-b')}<br>IDF(t)=ln(1+(N−df+.5)/(df+.5))`:`μ=${val('lm-mu')}<br>bars show exp(log P(query|document) / query_length)`}</div><p>${mode==='bm25'?'D1 is concise and repeats key terms. D6 contains all three terms but is much longer. Set b=0 to remove the length penalty. This is one BM25 variant, not a guarantee of the same numeric score in every search engine.':'The bars show geometric mean token probability for readability, preserving likelihood order for this fixed query. Ranking uses the sum of log probabilities and counts repeated query tokens.'}</p>`;}
function updateExpansion(){const mode=val('exp-mode'),w=number('exp-weight'),q={power:1,after:1,sunset:1};let extra={},description='Original words alone have no literal overlap with these body tokens.';if(mode==='synonym'){extra={electricity:w,night:w};description='Controlled mappings: power → electricity; sunset → night. These are context-specific examples, not universal synonyms.';}if(mode==='pseudo'){const initial=lexical({power:1,after:1,sunset:1,electricity:1},'cosine'),top=initial[0].d;extra=Object.fromEntries([...new Set(top.tokens)].filter(t=>!q[t]).slice(0,5).map(t=>[t,w]));description=`A preliminary controlled expansion adds “electricity”, then the top document ${top.id} supplies its first five new unique tokens. This toy rule illustrates pseudo-feedback, not RM3.`;}if(mode==='hyde'){extra={solar:w,battery:w,storage:w,electricity:w,night:w};description='Fixed hypothesis: “Solar battery storage saves electricity for night.” The demo searches its weighted tokens lexically; actual HyDE encodes a generated document with a dense model.';}const weighted={...q,...extra},res=lexical(weighted).filter(x=>x.score>0);$('#expansion-result').innerHTML=`<h3>${res.length?res.length+' documents become reachable.':'The vocabulary gap is visible.'}</h3><div class="tile-row">${Object.entries(weighted).filter(([t,v])=>v>0).map(([t,v])=>`<span class="term-tile">${esc(t)} · ${num(v,1)}</span>`).join('')}</div>${rows(res)}<p>${description}</p><p>All ranking values are computed TF–IDF cosine scores. This lab compares reformulations, not the measured performance of the cited algorithms.</p>`;}
const denseVectors=[{id:'A',label:'A · grid storage',v:[.95,.2]},{id:'B',label:'B · electric car',v:[.65,.85]},{id:'C',label:'C · overnight electricity',v:[.85,.1]},{id:'D',label:'D · transport policy',v:[.1,.95]}];
function updateDense(){const θ=number('dense-angle')*Math.PI/180,q=[Math.cos(θ),Math.sin(θ)],metric=val('dense-metric'),points=denseVectors.map(x=>({...x,v:x.v.map(v=>v*(x.id==='B'&&checked('dense-scale')?3:1))})),ranked=points.map(x=>({label:x.label,score:metric==='dot'?dot(q,x.v):cosine(q,x.v),sub:`[${x.v.map(v=>num(v,2)).join(', ')}]`})).sort((a,b)=>b.score-a.score);$('#dense-result').innerHTML=`<h3>${metric==='dot'?'Norm can change the winner.':'Direction defines the neighbors.'}</h3><svg class="geom" viewBox="0 0 360 205" role="img" aria-label="Two-dimensional query and document directions"><path d="M35 170H330 M35 170V15" stroke="#9daf9d" fill="none"/><text x="216" y="193" font-size="9" fill="#657278">energy-storage axis →</text><text x="4" y="12" font-size="9" fill="#657278">transport ↑</text>${denseVectors.map(x=>`<circle cx="${35+x.v[0]*270}" cy="${170-x.v[1]*140}" r="5" fill="#8ab29c"/><text x="${43+x.v[0]*270}" y="${173-x.v[1]*140}" font-size="10" fill="#315a4b">${x.id}</text>`).join('')}<path d="M35 170L${35+q[0]*270} ${170-q[1]*140}" stroke="#ba583c" stroke-width="2"/><circle cx="${35+q[0]*270}" cy="${170-q[1]*140}" r="5" fill="#ba583c"/><text x="${39+q[0]*270}" y="${162-q[1]*140}" font-size="10" fill="#ba583c">q</text></svg>${rows(ranked)}<div class="formula">q=[${q.map(v=>num(v,3)).join(', ')}] · ||q||=1</div><p>The plot shows original document coordinates; the score list uses the optional 3× scaling of B. Cosine is unchanged by positive scaling. Dot product rewards magnitude as well as alignment.</p>`;}
function updateSparse(){let x=number('sparse-expansion'),threshold=number('sparse-threshold'),raw={renewable:1,storage:1,battery:.9*x,solar:.75*x,grid:.45*x},q=Object.fromEntries(Object.entries(raw).map(([t,w])=>[t,w>=threshold?w:0])),documents=[{label:'A · battery + grid',v:{battery:1,grid:.8}},{label:'B · renewable policy',v:{renewable:.7,policy:1}},{label:'C · general storage',v:{storage:.55}},{label:'D · solar electricity',v:{solar:.9,electricity:.8}}],res=documents.map(d=>({label:d.label,score:Object.entries(q).reduce((s,[t,v])=>s+v*(d.v[t]||0),0),sub:Object.entries(d.v).map(([t,v])=>`${t}=${v}`).join(', ')})).sort((a,b)=>b.score-a.score);$('#sparse-result').innerHTML=`<h3>${Object.values(q).filter(w=>w>0).length} active query dimensions.</h3><div class="tile-row">${Object.entries(raw).map(([t,w])=>`<span class="term-tile ${!q[t]?'off':''}">${t} · ${num(w,2)}</span>`).join('')}</div>${rows(res)}<div class="formula">score(A) = ${num(q.battery)} × 1 + ${num(q.grid)} × .8 = ${num(res.find(d=>d.label.startsWith('A')).score)}</div><p>Query and document weights are visible teaching fixtures. The browser applies pruning and computes sparse dot products. It does not run SPLADE or learn weights.</p>`;}
const lateMatrices={balanced:{tokens:['solar','cells','battery'],matrix:[[.9,.65,.25],[.2,.3,.8]]},one:{tokens:['solar','roof','cost'],matrix:[[.98,.6,.25],[.12,.1,.18]]},duplicate:{tokens:['solar','battery','battery'],matrix:[[.9,.25,.25],[.2,.8,.8]]}};
function updateLate(){let {tokens,matrix}=lateMatrices[val('late-doc')],qs=checked('late-storage')?['solar','storage']:['solar'],sums=qs.map((_,i)=>Math.max(...matrix[i])),score=sums.reduce((a,b)=>a+b,0);$('#late-result').innerHTML=`<h3>MaxSim = ${num(score,2)}</h3><div class="table-wrap"><table class="mini-table matrix"><thead><tr><th>query ↓ / document →</th>${tokens.map(t=>`<th>${t}</th>`).join('')}<th>max</th></tr></thead><tbody>${qs.map((q,i)=>`<tr><th>${q}</th>${matrix[i].map(v=>`<td class="${v===sums[i]?'max':''}">${num(v,2)}</td>`).join('')}<td class="max">${num(sums[i],2)}</td></tr>`).join('')}</tbody></table></div><div class="formula">${sums.map(v=>num(v,2)).join(' + ')} = ${num(score,2)}</div><p>Each query token chooses its best support independently. Ties are highlighted together, but each row contributes its maximum only once. A document token can be reused for several query tokens; this is not a one-to-one matching problem.</p>`;}
const ivfClusters=[{id:'A',c:[.3,.25],points:[{id:'A1',v:[.24,.3]},{id:'A2',v:[.44,.47]}]},{id:'B',c:[.7,.65],points:[{id:'B1',v:[.54,.5]},{id:'B2',v:[.77,.8]}]},{id:'C',c:[.2,.85],points:[{id:'C1',v:[.3,.85]},{id:'C2',v:[.12,.9]}]}];
const distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
function ivfResults(n,y){let q=[.5,y],clusters=[...ivfClusters].sort((a,b)=>distance(q,a.c)-distance(q,b.c)),visited=clusters.slice(0,n),all=ivfClusters.flatMap(c=>c.points),exact=[...all].sort((a,b)=>distance(q,a.v)-distance(q,b.v)).slice(0,2),approx=visited.flatMap(c=>c.points).sort((a,b)=>distance(q,a.v)-distance(q,b.v)).slice(0,2);return{q,visited,all,exact,approx,recall:approx.filter(d=>exact.some(x=>x.id===d.id)).length/2};}
function updateIVF(){let r=ivfResults(number('ivf-probe'),number('ivf-y')),map=v=>[25+v[0]*310,180-v[1]*165];$('#indexes-result').innerHTML=`<h3>${r.visited.length} of 3 clusters searched.</h3><svg class="geom" viewBox="0 0 360 205" role="img" aria-label="IVF-style cluster probing, with centroids, document points and query"><path d="M25 15V180H345" stroke="#b5c7b5" fill="none"/>${ivfClusters.map(c=>{let [x,y]=map(c.c),on=r.visited.includes(c);return `<circle cx="${x}" cy="${y}" r="49" fill="${on?'#d9e7d6':'#efeee7'}" stroke="${on?'#a9c8af':'#dedfd8'}"/><path d="M${x-4} ${y-4}l8 8m-8 0l8-8" stroke="#657278"/><text x="${x+7}" y="${y-7}" fill="#657278" font-size="9">centroid ${c.id}</text>${c.points.map(p=>{let [px,py]=map(p.v);return `<circle cx="${px}" cy="${py}" r="4" fill="${on?'#087a72':'#aab6aa'}"/><text x="${px+6}" y="${py+5}" font-size="9" fill="#315a4b">${p.id}</text>`;}).join('')}`;}).join('')}<circle cx="${map(r.q)[0]}" cy="${map(r.q)[1]}" r="5" fill="#ba583c"/><text x="${map(r.q)[0]+7}" y="${map(r.q)[1]+3}" font-size="10" fill="#ba583c">query</text></svg>${metrics([[num(r.recall*100,0)+'%','ANN Recall@2'],[r.visited.length*2+'/6','document distances'],['2','returned items']])}<div class="formula">Exact top-2: ${r.exact.map(x=>x.id).join(', ')}<br>Probed top-2: ${r.approx.map(x=>x.id).join(', ')}</div><p>Query=[.50, ${num(r.q[1],2)}]. Cluster assignments are fixed teaching data. Work shown counts only document distances, excluding the three centroid comparisons. More probes reach the exact scan when all three are searched.</p>`;}
const semantic=[.91,.98,.2,.6,.08,.8,.72,.03];
const rerankScores=[.96,.99,.08,.52,.03,.83,.6,.01];
function updateRanking(){const depth=number('rerank-depth'),retrieved=bm25('solar battery storage').slice(0,depth),ranked=checked('rerank-on')?retrieved.map(x=>({...x,score:rerankScores[DOCS.indexOf(x.d)]})).sort((a,b)=>b.score-a.score):retrieved;let rel=retrieved.filter(x=>x.d.rel>0).length;$('#ranking-result').innerHTML=`<h3>${checked('rerank-on')?'Same candidates. A new order.':'The first-stage order.'}</h3>${rows(ranked)}${metrics([[depth,'candidates scored'],[num(rel/5*100,0)+'%','candidate Recall'],[retrieved.some(x=>x.d.id==='D2')?'IN':'OUT','D2 in shortlist']])}<p>BM25 source order: ${retrieved.map(x=>x.d.id).join(' → ')}. D2 is highly relevant by our teaching judgment but shares none of the three query words; a full-depth shortlist reaches it only in the zero-score tail. Reranker values are synthetic scores, not calibrated probabilities.</p>`;}
function minmax(items){const vs=items.map(x=>x.score),lo=Math.min(...vs),hi=Math.max(...vs);return Object.fromEntries(items.map(x=>[x.d.id,hi===lo?0:(x.score-lo)/(hi-lo)]));}
function fusionResults(depth,k,alpha,duplicate=false,mode='rrf'){let a=bm25('solar battery storage').slice(0,depth),b=DOCS.map((d,i)=>({d,score:semantic[i]})).sort((a,b)=>b.score-a.score).slice(0,depth),ids=[...new Set([...a,...b].map(x=>x.d.id))],na=minmax(a),nb=minmax(b);let ranked=ids.map(id=>{const ar=a.findIndex(x=>x.d.id===id),br=b.findIndex(x=>x.d.id===id),ac=ar<0?0:alpha/(k+ar+1),bc=br<0?0:(1-alpha)/(k+br+1);return{d:DOCS.find(d=>d.id===id),ar:ar<0?null:ar+1,br:br<0?null:br+1,ac,bc,score:mode==='score'?(alpha*(na[id]||0)*(duplicate?2:1)+(1-alpha)*(nb[id]||0)):(ac*(duplicate?2:1)+bc)};}).sort((x,y)=>y.score-x.score||x.d.id.localeCompare(y.d.id));return{a,b,ranked};}
function mmrSelect(items,lambda){const max=Math.max(...items.map(x=>x.score),.00001),remaining=items.map(x=>({...x,relevance:x.score/max})),selected=[];while(remaining.length){remaining.forEach(x=>{x.redundancy=selected.length?Math.max(...selected.map(y=>{let xs=new Set(x.d.tokens),ys=new Set(y.d.tokens),union=new Set([...xs,...ys]);return [...xs].filter(t=>ys.has(t)).length/union.size;})):0;x.mmr=lambda*x.relevance-(1-lambda)*x.redundancy;});remaining.sort((a,b)=>b.mmr-a.mmr||b.relevance-a.relevance||a.d.id.localeCompare(b.d.id));selected.push(remaining.shift());}return selected;}
function updateFusion(){let mode=val('fusion-mode'),depth=number('fusion-depth'),alpha=number('fusion-alpha'),k=number('fusion-k'),dup=checked('fusion-duplicate'),r=fusionResults(depth,k,mode==='mmr'?.5:alpha,dup,mode);$('#fusion-k').disabled=mode==='score';let ranked=mode==='mmr'?mmrSelect(r.ranked,alpha):r.ranked;$('#fusion-result').innerHTML=`<h3>${mode==='rrf'?'Rank positions become votes.':mode==='score'?'Scale first. Then blend.':'Prefer useful, complementary evidence.'}</h3><div class="formula">Lexical: ${r.a.map(x=>x.d.id).join(' → ')}<br>Semantic: ${r.b.map(x=>x.d.id).join(' → ')}${dup?'<br>+ a second copy of the lexical list':''}</div><div class="table-wrap"><table class="mini-table"><thead><tr><th>Item</th><th>Lex rank</th><th>Sem rank</th><th>${mode==='mmr'?'MMR at selection':'Fused score'}</th></tr></thead><tbody>${ranked.map(x=>`<tr><td>${x.d.id} · ${esc(x.d.title)}</td><td>${x.ar||'—'}</td><td>${x.br||'—'}</td><td class="hit">${num(mode==='mmr'?x.mmr:x.score,5)}</td></tr>`).join('')}</tbody></table></div>${mode==='rrf'&&ranked.length?`<div class="formula">${ranked[0].d.id}: lexical ${num(ranked[0].ac,5)}${dup?' × 2':''} + semantic ${num(ranked[0].bc,5)} = ${num(ranked[0].score,5)}</div>`:''}<p>${mode==='rrf'?`α=${num(alpha,2)}, k=${k}. Absent items contribute zero. Deduplication uses document ID. Rank ties resolve by document ID. A duplicate source adds another vote; it is not independent evidence.`:mode==='score'?'Each truncated list is min–max normalized independently; absent scores are 0. A constant or one-item list normalizes to 0 by this stated convention. Changing depth changes normalization. This is an illustrative blend, not calibrated probabilities.':`MMR uses equal-weight RRF (k=${k}) normalized by its maximum as relevance. Redundancy is body-token set Jaccard similarity. The empty selected set has redundancy 0; ties prefer higher relevance, then ID. Negative MMR values can occur.`}</p>`;}
function updateGraph(){let mode=val('graph-mode'),edge=checked('graph-edge'),two=mode==='two',summary=mode==='summary';$('#structured-result').innerHTML=`<h3>${summary?'Overview plus source pointers.':two?'Two links connect the answer.':'The first hop finds a product.'}</h3><svg class="geom" viewBox="0 0 370 125" role="img" aria-label="Synthetic graph: Aurora makes Cell A, Cell A uses sodium"><rect x="5" y="28" width="95" height="45" rx="6" fill="#e2eadd" stroke="#bad1bb"/><text x="52" y="55" text-anchor="middle" font-size="13" fill="#203439">Aurora</text><path d="M100 50H140" stroke="#087a72"/><text x="120" y="40" text-anchor="middle" font-size="9" fill="#657278">makes</text><rect x="140" y="28" width="90" height="45" rx="6" fill="#e2eadd" stroke="#bad1bb"/><text x="185" y="55" text-anchor="middle" font-size="13" fill="#203439">Cell A</text><path d="M230 50H270" stroke="${edge?'#087a72':'#c8c9bd'}" stroke-dasharray="${edge?'0':'4 4'}"/><text x="250" y="40" text-anchor="middle" font-size="9" fill="#657278">uses</text><rect x="270" y="28" width="95" height="45" rx="6" fill="${edge?'#f5e8dd':'#efeee7'}" stroke="#d8cdbb"/><text x="317" y="55" text-anchor="middle" font-size="13" fill="#203439">sodium</text><text x="53" y="100" text-anchor="middle" font-size="8" fill="#657278">entity</text><text x="185" y="100" text-anchor="middle" font-size="8" fill="#657278">evidence E1</text><text x="317" y="100" text-anchor="middle" font-size="8" fill="#657278">evidence E2</text></svg><div class="formula">${summary?(edge?'Community note: Aurora’s Cell A uses sodium. Sources: E1 + E2.':'Community note: Aurora makes Cell A. Material evidence is missing; do not assert sodium.'):(two?(edge?'Aurora → Cell A → sodium<br>Answer supported by E1 + E2.':'Aurora → Cell A → [missing edge]<br>No supported material answer.'):'Aurora → Cell A<br>Product found; material still unresolved.')}</div><p>Graph records and company names are invented for teaching. The path is deterministic. If evidence E2 is unavailable, the summary is also restricted; a prior summary must not masquerade as fresh source evidence.</p>`;}
function updateVisual(){let mode=val('visual-mode'),table=val('visual-query')==='table',preserved=table?mode!=='text':mode==='visual';$('#multimodal-result').innerHTML=`<h3>${preserved?'The needed relationship is retained.':'The representation loses a clue.'}</h3><svg class="geom" viewBox="0 0 355 215" role="img" aria-label="Synthetic page containing a labeled table and two declining chart curves"><rect x="30" y="8" width="290" height="198" rx="5" fill="#fffefa" stroke="#bac8b9"/><text x="49" y="32" font-family="Georgia" font-size="14" fill="#203439">Storage performance · teaching data</text><path d="M48 44H302 M48 68H302 M48 91H302 M48 113H302 M137 44V113 M222 44V113" stroke="#d5dfd0"/><text x="52" y="60" font-size="9" fill="#657278">Option</text><text x="147" y="60" font-size="9" fill="#657278">Cost units</text><text x="233" y="60" font-size="9" fill="#657278">Cycles</text><text x="52" y="83" font-size="10" fill="#203439">A</text><text x="153" y="83" font-size="10" fill="#203439">70</text><text x="239" y="83" font-size="10" fill="#203439">1500</text><text x="52" y="106" font-size="10" fill="#203439">B</text><text x="153" y="106" font-size="10" fill="#203439">90</text><text x="239" y="106" font-size="10" fill="#203439">3000</text><path d="M52 126V187H297" stroke="#a7bba7" fill="none"/><path d="M59 133L126 142L199 154L282 166" stroke="#087a72" fill="none" stroke-width="2"/><path d="M59 134L126 150L199 171L282 181" stroke="#ba583c" fill="none" stroke-width="2"/><text x="285" y="166" font-size="9" fill="#087a72">A</text><text x="285" y="182" font-size="9" fill="#ba583c">B</text></svg><div class="formula">${mode==='text'?'Flat token bag: A B 70 90 1500 3000 performance cost cycles':mode==='layout'?'Rows: A → cost 70, cycles 1500<br>B → cost 90, cycles 3000':'Page regions: title + structured table + plotted curves'}</div><p>${table?(preserved?'Row structure associates B with 3000 cycles, supporting the comparison. A text-based pipeline can preserve tables too when parsing succeeds.':'The numbers survive, but this deliberately lossy token bag removes row and column associations. “Text-only” does not have to be this lossy; structured extraction can preserve the answer.'):(preserved?'The orange B curve declines faster in this drawing. Retaining pixels permits visual comparison; a trained model must still learn to interpret them correctly.':'Neither the token bag nor the retained table contains the plotted trajectory. You need the visual region, extracted chart data or a trustworthy description.')}</p><p>All numbers are synthetic. The status above reports information retained by this demonstration’s representation, not a model accuracy measurement.</p>`;}
function updateAgent(){let budget=number('agent-budget'),diverse=checked('agent-diverse'),steps=[['Search 1 · cost','Evidence C1: option A costs less in this invented scenario.','cost']];if(budget>1)steps.push(diverse?['Search 2 · durability','Evidence D1: option B lasts longer under the stated conditions.','durability']:['Search 2 · another cost page','Evidence C2 repeats the first cost comparison.','cost']);if(budget>2)steps.push(diverse?['Search 3 · verify comparability','Evidence V1 states a shared measurement setup.','conditions']:['Search 3 · cost summary','Evidence C3 summarizes the same cost claim.','cost']);let covered=new Set(steps.map(s=>s[2])),aspects=['cost','durability','conditions'],coverage=covered.size/3;$('#frontier-result').innerHTML=`<h3>${num(coverage*100,0)}% of required evidence aspects covered.</h3><div class="frontier-trace">${steps.map(([h,t])=>`<div class="trace-step"><strong>${h}</strong><small>${t}</small></div>`).join('')}</div><div class="tile-row">${aspects.map(a=>`<span class="term-tile ${covered.has(a)?'':'off'}">${a}</span>`).join('')}</div><p><strong>${covered.size===3?'Stop: all three aspects are supported in this trace.':'Unresolved: '+aspects.filter(a=>!covered.has(a)).join(', ')+'.'}</strong> More searches do not guarantee more evidence. This scripted example counts distinct aspects, not the reliability of the claims.</p>`;}
let evalOrder=[];
function evaluationPreset(){const p=val('eval-preset');evalOrder=p==='ideal'?[...DOCS].sort((a,b)=>b.rel-a.rel||a.id.localeCompare(b.id)).map(d=>d.id):p==='reverse'?[...DOCS].sort((a,b)=>a.rel-b.rel||a.id.localeCompare(b.id)).map(d=>d.id):p==='semantic'?DOCS.map((d,i)=>({d,s:semantic[i]})).sort((a,b)=>b.s-a.s).map(x=>x.d.id):bm25('solar battery storage').map(x=>x.d.id);updateEvaluation();}
function calcMetrics(order,k){const docs=order.slice(0,k).map(id=>DOCS.find(d=>d.id===id)),relevant=DOCS.filter(d=>d.rel>0).length,hits=docs.filter(d=>d.rel>0).length,first=docs.findIndex(d=>d.rel>0),dcg=docs.reduce((s,d,i)=>s+(2**d.rel-1)/Math.log2(i+2),0),ideal=[...DOCS].sort((a,b)=>b.rel-a.rel).slice(0,k).reduce((s,d,i)=>s+(2**d.rel-1)/Math.log2(i+2),0);let running=0,ap=docs.reduce((s,d,i)=>{if(d.rel>0){running++;return s+running/(i+1);}return s;},0)/relevant;return{precision:hits/k,recall:hits/relevant,rr:first<0?0:1/(first+1),ndcg:ideal?dcg/ideal:0,ap,dcg,idcg:ideal};}
function updateEvaluation(){let k=number('eval-k'),m=calcMetrics(evalOrder,k);$('#evaluation-result').innerHTML=`${metrics([[num(m.precision),'Precision@'+k],[num(m.recall),'Recall@'+k],[num(m.rr),'RR@'+k],[num(m.ndcg),'nDCG@'+k],[num(m.ap),'AP prefix / all relevant'],[num(m.dcg,2),'DCG@'+k]])}<div class="formula">DCG=${num(m.dcg,4)} · ideal DCG=${num(m.idcg,4)}<br>AP shown = Σ relevant ranks≤k Precision@rank / 5</div>${evalOrder.map((id,i)=>{let d=DOCS.find(d=>d.id===id);return `<div class="eval-row" style="${i>=k?'opacity:.48':''}"><span class="rank-pos">${i+1}</span><span>${d.id} · ${esc(d.title)}</span><span class="gain">grade ${d.rel}/3</span><span class="move"><button type="button" data-move="${i}" data-dir="-1" aria-label="Move ${id} up" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-dir="1" aria-label="Move ${id} down" ${i===evalOrder.length-1?'disabled':''}>↓</button></span></div>`;}).join('')}<p>Rows below k are dimmed and excluded from the metric numerators. All 5 relevant documents remain in the recall and AP denominator. At k=8, the displayed AP is ordinary full-list average precision. These are per-query values; mean metrics require several queries.</p>`;}
$('#evaluation-result').addEventListener('click',e=>{let b=e.target.closest('[data-move]');if(!b)return;let i=+b.dataset.move,j=i+(+b.dataset.dir);if(j<0||j>=evalOrder.length)return;[evalOrder[i],evalOrder[j]]=[evalOrder[j],evalOrder[i]];updateEvaluation();const moved=$(`[data-move="${j}"][data-dir="${b.dataset.dir}"]`);if(moved&&!moved.disabled)moved.focus({preventScroll:true});});
$('#eval-preset').addEventListener('input',evaluationPreset);$('#eval-reset').addEventListener('click',evaluationPreset);
let eraFilter='all',timelineSelection=0;
function renderTimeline(filter=eraFilter,selected=timelineSelection){eraFilter=filter;let events=DATA.timeline.map((t,i)=>({...t,index:i})).filter(t=>{let y=parseInt(t.year,10);return filter==='all'||filter==='early'&&y<2000||filter==='middle'&&y>=2000&&y<=2020||filter==='recent'&&y>=2021;});if(!events.some(t=>t.index===selected))selected=events[0].index;timelineSelection=selected;$$('[data-era]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.era===filter)));$('#timeline-list').innerHTML=events.map(t=>`<button class="timeline-event" type="button" data-milestone="${t.index}" aria-pressed="${t.index===selected}"><time>${t.year}</time><span><strong>${t.title}</strong><small>${CATS[t.category]?.name||'Evaluation'}</small><span class="print-only">${esc(t.text)}<br>Source: ${SOURCES[t.source].title}</span></span></button>`).join('');let t=DATA.timeline[selected],s=SOURCES[t.source];$('#timeline-detail').innerHTML=`<span class="eyebrow">A LANDMARK, IN CONTEXT</span><div class="big-year">${t.year}</div><h2>${t.title}</h2><p>${t.text}</p><span class="pill">${CATS[t.category]?.name||'Evaluation & tradeoffs'}</span><div class="source-line">READ THE SOURCE<a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><span>${esc(s.author)} · ${s.year}</span></div><a class="primary" href="#${t.category}">Explore this family <span>↗</span></a>`;}
$('#timeline-list').addEventListener('click',e=>{let b=e.target.closest('[data-milestone]');if(b){let i=+b.dataset.milestone;renderTimeline(eraFilter,i);$(`[data-milestone="${i}"]`).focus({preventScroll:true});}});$$('[data-era]').forEach(b=>b.addEventListener('click',()=>renderTimeline(b.dataset.era)));
function renderPapers(){const query=val('paper-search').toLowerCase().trim(),kind=val('paper-kind'),category=val('paper-category'),papers=DATA.sources.filter(s=>(kind==='all'||s.kind===kind)&&(category==='all'||s.category===category)&&`${s.title} ${s.author} ${s.why} ${s.category}`.toLowerCase().includes(query));$('#paper-count').textContent=`${papers.length} of ${DATA.sources.length} references`;$('#paper-list').innerHTML=papers.length?papers.map(s=>`<article class="paper" id="paper-${s.id}"><div class="paper-year">${s.year}</div><div><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></h3><p class="authors">${esc(s.author)}</p><p>${esc(s.why)}</p><span class="pill">${esc(s.kind)}</span><span class="pill warm">${esc(s.category)}</span></div><a class="paper-open" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(s.title)}">↗</a></article>`).join(''):'<div class="empty">No sources match. Broaden the search or reset a filter.</div>';}
$('#global-search').addEventListener('input',()=>{const q=val('global-search').trim().toLowerCase(),box=$('#search-results');if(!q){box.hidden=true;box.innerHTML='';return;}let matches=DATA.categories.flatMap(c=>c.methods.map((m,i)=>({...m,category:c.id,categoryName:c.name,index:i}))).filter(m=>`${m.title} ${m.tag} ${m.idea} ${m.example}`.toLowerCase().includes(q));let papers=DATA.sources.filter(s=>`${s.title} ${s.author} ${s.category}`.toLowerCase().includes(q));box.hidden=false;box.innerHTML=`<p>${matches.length} method notes · ${papers.length} sources</p>${matches.slice(0,5).map(m=>`<button type="button" data-result-cat="${m.category}" data-result-index="${m.index}">${esc(m.title)}<small>${esc(m.categoryName)}</small></button>`).join('')}${papers.slice(0,2).map(s=>`<button type="button" data-result-paper="${s.id}">${esc(s.title)}<small>Paper / reading room</small></button>`).join('')}${!matches.length&&!papers.length?'<p>No matches. Try “fusion” or “feedback”.</p>':''}`;});
$('#search-results').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.resultCat){const id=b.dataset.resultCat;history.replaceState(null,'','#'+id);navigate(id,{scroll:false});const note=$(`#method-${id}-${b.dataset.resultIndex}`);note.open=true;note.scrollIntoView({block:'start'});$('summary',note).focus({preventScroll:true});}else if(b.dataset.resultPaper){$('#paper-search').value=SOURCES[b.dataset.resultPaper].title;$('#paper-kind').value='all';$('#paper-category').value='all';renderPapers();history.replaceState(null,'','#sources');navigate('sources');$('#paper-search').focus({preventScroll:true});}$('#global-search').value='';$('#search-results').hidden=true;});

bind(['bool-query','bool-filter'],updateBoolean);bind(['lex-query','lex-mode'],updateLexical);bind(['bm-query','bm-mode','bm-k1','bm-b','lm-mu'],updateBM);bind(['exp-mode','exp-weight'],updateExpansion);bind(['dense-angle','dense-metric','dense-scale'],updateDense);bind(['sparse-expansion','sparse-threshold'],updateSparse);bind(['late-doc','late-storage'],updateLate);bind(['ivf-probe','ivf-y'],updateIVF);bind(['rerank-depth','rerank-on'],updateRanking);bind(['fusion-mode','fusion-depth','fusion-k','fusion-alpha','fusion-duplicate'],updateFusion);bind(['graph-mode','graph-edge'],updateGraph);bind(['visual-mode','visual-query'],updateVisual);bind(['agent-budget','agent-diverse'],updateAgent);bind(['eval-k'],()=>{if(evalOrder.length)updateEvaluation();});bind(['paper-search','paper-kind','paper-category'],renderPapers);evaluationPreset();renderTimeline();navigate(location.hash.slice(1)||'overview',{scroll:false});
window.RETRIEVAL_READY=true;
window.RetrievalAtlas={bm25,lexical,booleanAST,matchAST,ivfResults,fusionResults,mmrSelect,calcMetrics,docs:DOCS,data:DATA};
